class Solver:
    def __init__(self, g, p, q):
        self.g = g  # Base
        self.p = p  # Módulo para pow()
        self.q = q  # Módulo final

    def find_k(self, target_r):
        """Encuentra el valor de k tal que (g^k mod p) mod q == target_r."""
        for k in range(65536, 1000000):
            r = pow(self.g, k, self.p) % self.q
            if r == target_r:
                return k  # Retorna el k encontrado
        return None  # Si no se encontró
    
    def find_x(s, k, h_hex, r, q):
        h = int(h_hex, 16)
        k_s = k * s
        numerator = (k_s - h) % q
        r_inv = pow(r, -1, q)
        x = (numerator * r_inv) % q
        return x

